float vrchVeilHash(vec2 point) {
  return fract(sin(dot(point, vec2(41.73, 289.19))) * 43758.5453);
}
float vrchVeilNoise(vec2 point) {
  vec2 cell = floor(point);
  vec2 local = fract(point);
  vec2 eased = local * local * (3.0 - 2.0 * local);
  float a = vrchVeilHash(cell);
  float b = vrchVeilHash(cell + vec2(1.0, 0.0));
  float c = vrchVeilHash(cell + vec2(0.0, 1.0));
  float d = vrchVeilHash(cell + vec2(1.0, 1.0));
  return mix(mix(a, b, eased.x), mix(c, d, eased.x), eased.y);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 resolution = max(iResolution.xy, vec2(1.0));
  vec2 uv = fragCoord / resolution;
  vec4 image = vrchSampleSource0(uv);
  vec2 aspect = vec2(resolution.x / resolution.y, 1.0);
  vec2 point = uv * aspect * uParam_scale + vec2(iTime * uParam_speed, -iTime * uParam_speed * 0.37);
  float broad = vrchVeilNoise(point);
  float medium = vrchVeilNoise(point * 2.03 + vec2(7.1, 3.4));
  float fine = vrchVeilNoise(point * 4.07 - vec2(2.8, 5.6));
  float field = broad * 0.58 + medium * 0.29 + fine * 0.13;
  float lowerDrift = 1.0 - smoothstep(0.18, 1.15, uv.y + field * 0.24);
  float veil = smoothstep(0.58 - uParam_softness * 0.22, 0.82, field) * mix(0.52, 1.0, lowerDrift);
  float edge = smoothstep(0.48, 0.72, abs(field - 0.54) * 2.0) * 0.18;
  float mask = clamp(veil + edge, 0.0, 1.0);
  vec3 treated = image.rgb * (1.0 - mask * 0.08) + uParam_color.rgb * mask * uParam_brightness;
  fragColor = vec4(mix(image.rgb, treated, uParam_amount), image.a);
}
